local FishPoolActivityFeedNode1 = Class("FishPoolActivityFeedNode1")
function FishPoolActivityFeedNode1:__init() 
    self._activityId = 0
    self._allData = {}
end

function FishPoolActivityFeedNode1:__delete()
    self._activityId = 0
    self._allData = {}
end

function FishPoolActivityFeedNode1:Awake()    
end

function FishPoolActivityFeedNode1:Start()
    self.EventEveryThingChangeEventName = Events.AddListener(Constants.EventNames.EveryThingChangeEventName, Bind(self, self.OnEveryThingChangeEventName))
end

function FishPoolActivityFeedNode1:OnEveryThingChangeEventName(body)
    local vo = FishingUtils.GetFishActivityPlanVo(self._activityId)
    CfUtils.FillText(self.TextNumber, GoodsUtils.GetThingNo(vo.properties))
end

function FishPoolActivityFeedNode1:Refresh(activityId)
    self._activityId = activityId

    self:InitData()
    self:FillSelf()

    local vo = FishingUtils.GetFishActivityPlanVo(self._activityId)
    local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
    CriWareUtils.PlayVoice("Audio/UI_General", "ui_fishActivity_whoosh_"..vo.changeId)
end

function FishPoolActivityFeedNode1:OnShow(activityId)
    self:PlaySpine("Play", false)
end

function FishPoolActivityFeedNode1:PlaySpine(name, isLoop)
    if self._co then
        cs_coroutine.stop(self._co)
        self._co = nil
    end

    self._co = cs_coroutine.start(function()
        CfUtils.PlaySpine(self.Container.transform:Find("BgNode/Cat"), name, isLoop)
        coroutine.yield(WaitForSeconds(CfUtils.GetSpineTime(self.Container.transform:Find("BgNode/Cat"), name)))
        CfUtils.PlaySpine(self.Container.transform:Find("BgNode/Cat"), "Idle", true)
    end)
end

function FishPoolActivityFeedNode1:InitData()
    local t = FishingUtils.GetAllExChangeData(self._activityId)
    self._allData = t
end

function FishPoolActivityFeedNode1:FillSelf()
    if not self._isInit then
        self.ScrollView:InitListView(#self._allData, Bind(self, self.OnGetItemByIndex))
        self._isInit = true
    else
        GameUtils.ReloadData(self.ScrollView, 0)
        GameUtils.ReloadData(self.ScrollView, #self._allData)
    end

    local vo = FishingUtils.GetFishActivityPlanVo(self._activityId)
    CfUtils.FillText(self.TextNumber, GoodsUtils.GetThingNo(vo.properties))

    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.properties)
    CfUtils.FillImage(self.ImgGoods, goodsVo.photoPath)

    SetButtonAction(self.BtnGoods, function()
        GameUtils.ShowCommonTipsBoard(self.BtnGoods.gameObject, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
    end)

    local ind = 0
    local id = 0
    for k, v in pairs(self._allData) do
        if FishingUtils.IsUnlockExchangeReward(v) then
            if checkNumber(v) > checkNumber(id) then
                id = v
                ind = k
            end
        end
    end
    self.ScrollView:MovePanelToItemIndex(ind - 2)

    CfUtils.FillText(self.Text, vo.desc)
end

function FishPoolActivityFeedNode1:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local data = FishingUtils.GetFishingExChangeVo(self._allData[index + 1])
    local cell
    if checkNumber(data.type) == 2 then
        cell = listView:NewListViewItem("Cell2")
    else
        cell = listView:NewListViewItem("Cell1")
    end

    local scr = CfUtils.GetLuaScr(cell.gameObject, "Game.UI.Fishing.FishPoolActivityFeedDialog.FishPoolActivityFeedCellNode")
    if scr then
        scr:Refresh(data, self)
    end

    return cell
end

function FishPoolActivityFeedNode1:OnDestroy()
    GameUtils.SetRedPointNum(Constants.RedPointConst.PhoneFishActivityExchange, FishingUtils.IsHaveCanDrawExchangeReward() and 1 or 0)
    Events.RemoveListener(Constants.EventNames.EveryThingChangeEventName, self.EventEveryThingChangeEventName)
    if self._co then
        cs_coroutine.stop(self._co)
        self._co = nil
    end

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return FishPoolActivityFeedNode1
